INSERT INTO user_skills(user_id,skill_id) SELECT u.id,s.id FROM (SELECT 1 uid,'Python,SQL,Machine Learning' vals UNION SELECT 2,'SQL,PHP,Web Development' UNION SELECT 3,'JavaScript,Web Development,UI Design' UNION SELECT 4,'Java,Data Structures,Git' UNION SELECT 5,'Python,Machine Learning,Excel' UNION SELECT 6,'Python,Excel,Power BI' UNION SELECT 7,'Java,SQL,UI Design' UNION SELECT 8,'JavaScript,PHP,Git' UNION SELECT 9,'SQL,Python,Computer Networks' UNION SELECT 10,'Power BI,Excel,Data Structures') x JOIN users u ON u.id=x.uid JOIN skills s ON FIND_IN_SET(s.name,x.val);
INSERT INTO user_subjects(user_id,subject_id,intent) SELECT x.uid,s.id,x.intent FROM (SELECT 1 uid,'DBMS' nm,'help' intent UNION SELECT 1,'Machine Learning','want' UNION SELECT 2,'DBMS','help' UNION SELECT 2,'Web Development','help' UNION SELECT 3,'Web Development','want' UNION SELECT 3,'Software Engineering','help' UNION SELECT 4,'Data Structures','help' UNION SELECT 4,'Java','help' UNION SELECT 5,'Machine Learning','help' UNION SELECT 5,'Statistics','want' UNION SELECT 6,'Python','help' UNION SELECT 6,'Statistics','help' UNION SELECT 7,'Operating Systems','want' UNION SELECT 7,'Java','want' UNION SELECT 8,'Web Development','help' UNION SELECT 8,'JavaScript','help' UNION SELECT 9,'DBMS','want' UNION SELECT 9,'Computer Networks','want' UNION SELECT 10,'Data Structures','want' UNION SELECT 10,'Mathematics','help') x JOIN subjects s ON s.name=x.nm;
